css:
.uic-wrapper {
  --pill-width: 200px;
  --pill-height: 70px;
  --knob-size: 90px;
  --accent: #c56a3a;

  padding: 60px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pill-toggle {
  position: relative;
  display: inline-block;
  width: var(--pill-width);
  height: var(--pill-height);
}
.pill-toggle input {
  display: none;
}
.track {
  width: 100%;
  height: 100%;
  background: #d0d0d0;
  border-radius: 999px;
  box-shadow:
    inset 0 2px 6px rgba(0, 0, 0, 0.15),
    inset 0 4px 12px rgba(0, 0, 0, 0.05),
    0 1px 0 rgba(255, 255, 255, 0.4);
  position: relative;
  transition: background 0.4s ease;
}
.pill {
  position: absolute;
  top: -8.8%;
  left: -5%;
  width: var(--knob-size);
  height: 110%;
  border-radius: 999px;
  cursor: pointer;

  background: linear-gradient(to bottom, #e6e6e6, #cfcfcf);

  box-shadow:
    0 1px 0 var(--accent),
    0 8px 15px rgba(0, 0, 0, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);

  transition: all 0.7s cubic-bezier(0.34, 1.56, 0.64, 1);
  z-index: 2;
}

.pill-surface {
  position: absolute;
  inset: 5%;
  border-radius: 999px;
  background: linear-gradient(135deg, #f4f4f4 0%, #dedede 45%, #cfcfcf 100%);

  box-shadow:
    inset 0 -1px 2px rgba(0, 0, 0, 0.1),
    inset 0 1px 2px rgba(255, 255, 255, 0.8);
}

.pill-toggle:hover .pill {
  transform: translateY(-1px);

  box-shadow:
    0 4px 0 var(--accent),
    0 15px 25px rgba(0, 0, 0, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.pill-toggle input:active + .track .pill {
  transform: translateY(2px);
  box-shadow:
    0 2px 0 var(--accent),
    0 2px 6px rgba(0, 0, 0, 0.15),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
  transition: all 0.1s ease;
}
.pill-toggle input:checked + .track .pill {
  left: calc(105% - var(--knob-size));
}

.pill-toggle input:checked + .track {
  background: #e4e4e4;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.1);
}
